def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n <= 1:
        return 0  # No positive divisor smaller than n exists for n <= 1
    for i in range(n - 1, 1, -1):
        if n % i == 0:
            return i
    return 0  # Fallback, though n > 1 always has at least one divisor > 1
